const base = { plan: "free", seats: 1 };
const account = Object.create(base);
account.owner = "Kim";
account.seats = 3;

const copy = { ...account };
const saved = JSON.parse(JSON.stringify(account));

console.log(Object.keys(copy).join(","));
console.log(copy.plan, saved.plan, account.plan);
console.log(saved.seats, Object.getPrototypeOf(saved) === base);
